<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Core.php';use Wams\Core;
session_name('WAMS');session_start(['cookie_httponly'=>true,'cookie_samesite'=>'Lax','cookie_secure'=>isset($_SERVER['HTTPS'])]);$c=new Core();$error='';
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function go(string $url):never{header('Location: '.$url);exit;}
$path=trim((string)parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/');
if(preg_match('~^app/([a-f0-9]{32})(?:/(.*))?$~',$path,$m)){$u=$c->requireUser();$a=$c->app($m[1]);if(!$c->canUse($u,$a['id'])){http_response_code(403);exit;}$rel=$m[2]?:'index.php';$isAdmin=$rel==='admin.php';if($isAdmin&&!$c->canAdmin($u,$a['id'])){http_response_code(403);exit;}$root=realpath($c->cfg['apps'].'/'.$a['id']);$file=realpath($root.'/'.$rel);if(!$root||!$file||!str_starts_with($file,$root.'/')||!is_file($file)){http_response_code(404);exit;}$ext=strtolower(pathinfo($file,PATHINFO_EXTENSION));if($ext==='php'){$webapp_managed=true;$webapp_admin=$isAdmin;$webapp_user=$u;$webapp_instance=$a;$webapp_config_file=$root.'/csv-reporting.json';chdir($root);require$file;exit;}$types=['css'=>'text/css','js'=>'application/javascript','json'=>'application/json','svg'=>'image/svg+xml','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp','gif'=>'image/gif'];header('Content-Type: '.($types[$ext]??'application/octet-stream'));header('X-Content-Type-Options: nosniff');readfile($file);exit;}
$page=(string)($_GET['page']??($path==='login'?'login':'launcher'));
try{
 if($page==='logout'){session_destroy();go('/login');}
 if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){if($c->login(trim((string)$_POST['username']),(string)$_POST['password']))go('/');$error='Anmeldung fehlgeschlagen.';}
 if($page!=='login')$u=$c->requireUser();
 if(isset($u)&&$_SERVER['REQUEST_METHOD']==='POST'){$c->verifyCsrf();if(!$u['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');
  if($page==='repo-refresh'){$c->refreshRepository();go('/?page=store');}
  if($page==='install'){$found=null;foreach($c->catalog()as$item)if(($item['id']??'')===(string)$_POST['catalog_id'])$found=$item;if(!$found)throw new RuntimeException('App nicht gefunden.');$c->install($found);go('/?page=apps');}
  if($page==='user-create'){$name=trim((string)$_POST['username']);$pass=(string)$_POST['password'];if($name===''||strlen($pass)<12)throw new RuntimeException('Benutzername und mindestens 12 Zeichen Passwort erforderlich.');$c->db->prepare('INSERT INTO users VALUES(?,?,?,?,?,?)')->execute([$c->id(),$name,password_hash($pass,PASSWORD_ARGON2ID),0,1,gmdate('c')]);go('/?page=users');}
  if($page==='access'){$c->db->prepare('DELETE FROM user_apps WHERE user_id=? AND app_id=?')->execute([$_POST['user'],$_POST['app']]);if($_POST['mode']!=='none')$c->db->prepare('INSERT INTO user_apps VALUES(?,?,?)')->execute([$_POST['user'],$_POST['app'],$_POST['mode']==='admin'?1:0]);go('/?page=users');}
  if($page==='import'){$a=$c->app((string)$_POST['id']);$upload=$_FILES['json']??[];if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($upload['size']??0)>5242880)throw new RuntimeException('Importdatei ungueltig oder groesser als 5 MiB.');$raw=(string)file_get_contents($upload['tmp_name']);$data=json_decode($raw,true);if(!is_array($data))throw new RuntimeException('JSON ist ungueltig.');file_put_contents($c->cfg['apps'].'/'.$a['id'].'/csv-reporting.json',json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)."\n",LOCK_EX);go('/?page=apps');}
 }
 if(isset($u)&&$page==='export'){$a=$c->app((string)$_GET['id']);if(!$u['is_global_admin'])throw new RuntimeException('Nicht erlaubt.');$f=$c->cfg['apps'].'/'.$a['id'].'/csv-reporting.json';if(!is_file($f))file_put_contents($f,"{}\n");header('Content-Type: application/json');header('Content-Disposition: attachment; filename="csv-reporting.json"');readfile($f);exit;}
}catch(Throwable $e){$error=$e->getMessage();}
if($page==='login'):?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS</title></head><body class="login-page"><main class="login"><h1>WAMS</h1><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post"><label>Benutzername</label><input name="username" required autofocus><label>Passwort</label><input type="password" name="password" required><button>Anmelden</button></form></main></body></html><?php exit;endif;
if($page==='launcher'):$apps=array_filter($c->db->query('SELECT * FROM apps ORDER BY name')->fetchAll(),fn($a)=>$c->canUse($u,$a['id']));?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS</title></head><body class="launcher"><header class="launcher-head"><strong>WAMS</strong><div><?php if($u['is_global_admin']):?><a class="button secondary" href="/?page=apps">Verwaltung</a><?php endif?> <a class="button secondary" href="/?page=logout">Abmelden</a></div></header><?php if($apps):?><main class="grid"><?php foreach($apps as$a):?><a class="card" href="/app/<?=h($a['id'])?>/index.php"><strong><?=h($a['name'])?></strong></a><?php endforeach?></main><?php else:?><div class="empty">Keine Apps verfügbar.</div><?php endif?></body></html><?php exit;endif;
if(!$u['is_global_admin']){http_response_code(403);exit;}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/style.css"><title>WAMS Verwaltung</title></head><body><div class="shell"><aside class="sidebar"><div class="brand">WAMS</div><nav class="nav"><a href="/?page=apps">Apps</a><a href="/?page=store">App Store</a><a href="/?page=users">Benutzer</a><a href="/">Launcher</a><a href="/?page=logout">Abmelden</a></nav></aside><section class="main"><header class="topbar"><strong>Verwaltung</strong><span><?=h($u['username'])?></span></header><main class="content"><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<?php if($page==='apps'):$apps=$c->db->query('SELECT * FROM apps ORDER BY name')->fetchAll();?><section class="panel"><div class="panel-title">Installierte Apps</div><div class="panel-body"><table><tr><th>App</th><th>Aktionen</th></tr><?php foreach($apps as$a):?><tr><td><a href="/app/<?=h($a['id'])?>/index.php"><?=h($a['name'])?></a></td><td><div class="row"><a class="button secondary" href="/app/<?=h($a['id'])?>/admin.php">Admin</a><a class="button secondary" href="/?page=export&amp;id=<?=h($a['id'])?>">Export</a><form method="post" action="/?page=import" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="id" value="<?=h($a['id'])?>"><input type="file" name="json" accept=".json,application/json" required><button>Import</button></form></div></td></tr><?php endforeach?></table></div></section>
<?php elseif($page==='store'):?><div class="row"><form method="post" action="/?page=repo-refresh"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><button>Repository aktualisieren</button></form></div><div class="grid" style="margin-top:15px"><?php foreach($c->catalog()as$item):?><section class="card"><strong><?=h($item['name'])?></strong><small><?=h($item['id'])?></small><form method="post" action="/?page=install"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><input type="hidden" name="catalog_id" value="<?=h($item['id'])?>"><button style="margin-top:14px">Installieren</button></form></section><?php endforeach?></div>
<?php elseif($page==='users'):$users=$c->db->query('SELECT * FROM users ORDER BY username')->fetchAll();$apps=$c->db->query('SELECT * FROM apps ORDER BY name')->fetchAll();?><div class="grid"><section class="panel"><div class="panel-title">Benutzer anlegen</div><div class="panel-body"><form method="post" action="/?page=user-create"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Benutzername</label><input name="username" required><label>Passwort</label><input type="password" name="password" minlength="12" required><button style="margin-top:15px">Anlegen</button></form></div></section><section class="panel"><div class="panel-title">App-Zugriff</div><div class="panel-body"><form method="post" action="/?page=access"><input type="hidden" name="csrf" value="<?=h($c->csrf())?>"><label>Benutzer</label><select name="user"><?php foreach($users as$x):if($x['is_global_admin'])continue;?><option value="<?=h($x['id'])?>"><?=h($x['username'])?></option><?php endforeach?></select><label>App</label><select name="app"><?php foreach($apps as$a):?><option value="<?=h($a['id'])?>"><?=h($a['name'])?></option><?php endforeach?></select><label>Zugriff</label><select name="mode"><option value="none">Kein Zugriff</option><option value="app">App</option><option value="admin">App + Admin</option></select><button style="margin-top:15px">Speichern</button></form></div></section></div><?php endif?></main></section></div></body></html>
